package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Dues;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SettingRepository {

    /** The clerk limit: the largest due a clerk may settle (two decimals; blank: no limit). */
    public static final String CLERK_LIMIT = "clerk-limit";

    /** The floor: the least a claim's live due can be (two decimals). */
    public static final String FLOOR = "floor";

    /** The terms: the number of days after its date by which a claim is due (a whole number). */
    public static final String TERMS = "terms";

    /** The late percent: the share of an overdue claim's figure it gains for every full 30 days
     *  it is overdue (two decimals). */
    public static final String LATE_PCT = "late-pct";

    /** The late percent until it is first set. */
    public static final String DEFAULT_LATE_PCT = "0.00";

    /** The terms until they are first set. */
    public static final String DEFAULT_TERMS = "14";

    /** The floor until it is first set. */
    public static final String DEFAULT_FLOOR = "1.00";

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's settings that have been set, by key. */
    public List<Setting> list(String sheetId) {
        return jdbc.query("SELECT sheet_id, setting, val FROM sheet_setting WHERE sheet_id = ? ORDER BY setting",
                (rs, n) -> new Setting(rs.getString("sheet_id"), rs.getString("setting"),
                        rs.getString("val") == null ? "" : rs.getString("val")), sheetId);
    }

    /** The setting's value; null when blank or never set. */
    public String find(String sheetId, String key) {
        // A blank value is a null row value, which a stream's findFirst cannot carry.
        List<String> values = jdbc.query("SELECT val FROM sheet_setting WHERE sheet_id = ? AND setting = ?",
                (rs, n) -> rs.getString("val"), sheetId, key);
        return values.isEmpty() ? null : values.get(0);
    }

    /** The sheet's clerk limit; null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        String value = find(sheetId, CLERK_LIMIT);
        return value == null ? null : new BigDecimal(value);
    }

    /** The sheet's floor (two decimals). */
    public String floor(String sheetId) {
        String value = find(sheetId, FLOOR);
        return value == null ? DEFAULT_FLOOR : value;
    }

    /** The sheet's terms (whole days). */
    public int terms(String sheetId) {
        String value = find(sheetId, TERMS);
        return Integer.parseInt(value == null ? DEFAULT_TERMS : value);
    }

    /** The sheet's late percent (two decimals). */
    public String latePct(String sheetId) {
        String value = find(sheetId, LATE_PCT);
        return value == null ? DEFAULT_LATE_PCT : value;
    }

    /** What a claim's late charge goes by on the sheet now. */
    public Dues.Late late(String sheetId, LocalDate today) {
        return new Dues.Late(latePct(sheetId), terms(sheetId), today);
    }

    /** Set (or replace) the setting's value (null: blank). */
    public Setting set(String sheetId, String key, String value, String user) {
        jdbc.update("DELETE FROM sheet_setting WHERE sheet_id = ? AND setting = ?", sheetId, key);
        jdbc.update("INSERT INTO sheet_setting (sheet_id, setting, val, set_by, set_at) "
                + "VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)", sheetId, key, value, user);
        return new Setting(sheetId, key, value == null ? "" : value);
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSetting {
    /** 0 or more, with up to two decimals. */
    private static final Pattern MONEY = Pattern.compile("(\\d+(\\.\\d{0,2})?|\\.\\d{1,2})");

    /** A whole number of days, 0 or more. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,6}");

    public void validate(@RequestBody SettingRequest request, Out<SettingRequest> body)
            throws InvalidSettingException {
        String key = request == null || request.key() == null ? "" : request.key().trim();
        String value = request == null || request.value() == null ? "" : request.value().trim();
        if (SettingRepository.CLERK_LIMIT.equals(key)) {
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The clerk limit is blank or 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.FLOOR.equals(key)) {
            if (!MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The floor is 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.LATE_PCT.equals(key)) {
            if (!MONEY.matcher(value).matches()) {
                throw new InvalidSettingException("The late percent is 0.00 or more with up to two decimals");
            }
        } else if (SettingRepository.TERMS.equals(key)) {
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("The terms are a whole number of days, 0 or more");
            }
            body.set(new SettingRequest(key, String.valueOf(Integer.parseInt(value))));
            return;
        } else {
            throw new InvalidSettingException("Unknown setting: " + key);
        }
        body.set(new SettingRequest(key,
                value.isEmpty() ? null : new BigDecimal(value).setScale(2).toPlainString()));
    }
}
package net.officefloor.hq.app.claim;

/** A claim with a negative amount is a correction: allowed only when it names, by number, a SETTLED
 *  claim of the same person that it corrects. */
public final class Corrections {
    private Corrections() {
    }

    /** The number a claim corrects: none for a claim that is not a correction; refused when a
     *  correction names no SETTLED claim of the person. */
    public static Long check(ValidClaim request, String sheetId, long personId, ClaimRepository claims)
            throws InvalidClaimException {
        if (!request.isCorrection()) return null;
        Claim corrected = claims.findByNumber(sheetId, request.corrects());
        if (corrected == null || corrected.getPersonId() != personId
                || !ClaimStatus.SETTLED.name().equals(corrected.getStatus())) {
            throw new InvalidClaimException("A correction must name a SETTLED claim of the same person");
        }
        return request.corrects();
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { sheetKey } from '../sheet/api';
import type { Late } from '../rates/api';

/** A sheet setting: its value as text ("" when blank). A setting never set is not listed. */
export type Setting = { sheetId: string; key: string; value: string };
/** The role a user name has on the sheet; a name not listed is a clerk. */
export type Role = { sheetId: string; user: string; role: string };

/** The settings the screen offers: the clerk limit (two decimals; blank means no limit), the
 *  floor (two decimals; the least a claim's live due can be) and the terms (whole days after its
 *  date by which a claim is due) and the late percent (two decimals; the share of an overdue claim's
 *  figure it gains for every full 30 days it is overdue). */
export const SETTING_KEYS = ['clerk-limit', 'floor', 'terms', 'late-pct'] as const;

/** A setting's value until it is first set. */
export const SETTING_DEFAULTS: Record<string, string> = { floor: '1.00', terms: '14', 'late-pct': '0.00' };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const settingsKey = (sheetId: string) => [...sheetKey(sheetId), 'settings'] as const;
export const rolesKey = (sheetId: string) => [...sheetKey(sheetId), 'roles'] as const;

export function listSettings(sheetId: string): Promise<Setting[]> {
  return getJson<Setting[]>(`${base(sheetId)}/settings`);
}

/** Change a setting; refused (rejects) when the value is not valid for it. */
export function changeSetting(sheetId: string, by: string, key: string, value: string): Promise<Setting> {
  return postJson<Setting>(`${base(sheetId)}/settings?by=${encodeURIComponent(by)}`, { key, value });
}

export function listRoles(sheetId: string): Promise<Role[]> {
  return getJson<Role[]>(`${base(sheetId)}/roles`);
}

/** Assign a user name a role; refused (rejects) when the role is not clerk or steward. */
export function setRole(sheetId: string, by: string, user: string, role: string): Promise<Role> {
  return postJson<Role>(`${base(sheetId)}/roles?by=${encodeURIComponent(by)}`, { user, role });
}

/** The sheet's floor: the least a claim's live due can be. */
export function useFloor(sheetId: string): string {
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  return settings.data?.find((s) => s.key === 'floor')?.value || SETTING_DEFAULTS.floor;
}

/** What a claim's late charge goes by: the sheet's late percent, terms and today. */
export function useLate(sheetId: string, today: string): Late {
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  const pct = settings.data?.find((s) => s.key === 'late-pct')?.value || SETTING_DEFAULTS['late-pct'];
  return { pct, terms: useTerms(sheetId), today };
}

/** The sheet's terms: the number of days after its date by which a claim is due. */
export function useTerms(sheetId: string): number {
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  return Number(settings.data?.find((s) => s.key === 'terms')?.value || SETTING_DEFAULTS.terms);
}
