package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

@Repository
public class ClaimRepository {

    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, number, settled_due, opened_by, stated, stated_due, corrects";

    private static final RowMapper<Claim> ROW = (rs, n) -> withCorrects(new Claim(rs.getLong("id"),
            rs.getString("sheet_id"), rs.getLong("person_id"),
            rs.getBigDecimal("amount").setScale(2).toPlainString(),
            rs.getObject("claim_date", LocalDate.class).toString(), rs.getString("note"),
            rs.getString("status"), rs.getObject("number", Long.class),
            rs.getBigDecimal("settled_due") == null ? null
                    : rs.getBigDecimal("settled_due").setScale(2).toPlainString(),
            rs.getString("opened_by"), rs.getBoolean("stated"),
            rs.getBigDecimal("stated_due") == null ? null
                    : rs.getBigDecimal("stated_due").setScale(2).toPlainString()), rs.getObject("corrects", Long.class));

    private static Claim withCorrects(Claim claim, Long corrects) {
        claim.setCorrects(corrects);
        return claim;
    }

    private final JdbcTemplate jdbc;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY id DESC",
                ROW, sheetId);
    }

    public Claim find(String sheetId, long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?",
                ROW, sheetId, id).stream().findFirst().orElse(null);
    }

    /** The claim on the sheet with that number; null when none has it. */
    public Claim findByNumber(String sheetId, long number) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND number = ?",
                ROW, sheetId, number).stream().findFirst().orElse(null);
    }

    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            Long corrects, String user) {
        GeneratedKeyHolder key = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, created_by, corrects) "
                            + "VALUES (?, ?, ?, ?, ?, ?, ?)",
                    new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setObject(4, date);
            ps.setString(5, note);
            ps.setString(6, user);
            ps.setObject(7, corrects);
            return ps;
        }, key);
        return withCorrects(new Claim(key.getKey().longValue(), sheetId, personId, amount.toPlainString(),
                date.toString(), note, ClaimStatus.DRAFT.name(), null, null, null), corrects);
    }

    public void update(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, settled_due = ?, opened_by = ?, corrects = ? WHERE sheet_id = ? AND id = ?",
                new BigDecimal(claim.getAmount()), LocalDate.parse(claim.getDate()), claim.getNote(),
                claim.getStatus(), claim.getNumber(),
                claim.getSettledDue() == null ? null : new BigDecimal(claim.getSettledDue()),
                claim.getOpenedBy(), claim.getCorrects(),
                claim.getSheetId(), claim.getId());
    }

    /** The person's claims, newest first. */
    public List<Claim> listOf(String sheetId, long personId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC",
                ROW, sheetId, personId);
    }

    /** Save a claim's binding by its person's last statement. */
    public void updateBinding(Claim claim) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
                claim.isStated(), claim.getStatedDue() == null ? null : new BigDecimal(claim.getStatedDue()),
                claim.getSheetId(), claim.getId());
    }

    /** The sheet's next claim number, taken in one atomic statement so two claims opened at the same
     *  moment never get the same one; rolled back with the request when it is refused. */
    public long nextNumber(String sheetId) {
        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE ("
                + "UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)",
                Long.class, sheetId);
    }
}
package net.officefloor.hq.app.claim;

import com.fasterxml.jackson.annotation.JsonIgnore;

/** A claim of a person: an amount (two decimals, as text), a date (yyyy-MM-dd), a note and a status
 *  (a {@link ClaimStatus} name), and its number on the sheet (given when opened and kept when voided;
 *  none while a draft), its settled due (fixed when settled; none otherwise, or when there was no rate), and
 *  who opened it (none while a draft), and whether its person's last statement bound it, with the
 *  figure it bound (none when it had none): a bound claim shows and totals that figure. A correction (a
 *  negative amount) keeps the number of the SETTLED claim of its person it corrects (none otherwise). */
public class Claim {
    private final long id;
    private final String sheetId;
    private final long personId;
    private String amount;
    private String date;
    private String note;
    private String status;
    private Long number;
    private String settledDue;
    private String openedBy;
    private boolean stated;
    private String statedDue;
    private Long corrects;

    public Claim(long id, String sheetId, long personId, String amount, String date, String note,
            String status, Long number, String settledDue, String openedBy) {
        this(id, sheetId, personId, amount, date, note, status, number, settledDue, openedBy, false, null);
    }

    public Claim(long id, String sheetId, long personId, String amount, String date, String note,
            String status, Long number, String settledDue, String openedBy, boolean stated,
            String statedDue) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public String getAmount() { return amount; }
    public void setAmount(String amount) { this.amount = amount; }
    public String getDate() { return date; }
    public void setDate(String date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
    public Long getNumber() { return number; }
    public void setNumber(Long number) { this.number = number; }
    public String getSettledDue() { return settledDue; }
    public void setSettledDue(String settledDue) { this.settledDue = settledDue; }

    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }

    public Long getCorrects() { return corrects; }
    public void setCorrects(Long corrects) { this.corrects = corrects; }

    public boolean isStated() { return stated; }
    public String getStatedDue() { return statedDue; }

    /** Bind to a figure (null: none), or unbind when not {@code stated}. */
    public void bind(boolean stated, String statedDue) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
    }

    /** Whether it counts toward claimed, due-total and every total: only OPEN and SETTLED do. */
    @JsonIgnore
    public boolean isCounting() {
        return ClaimStatus.OPEN.name().equals(status) || ClaimStatus.SETTLED.name().equals(status);
    }

    /** The due it shows: the one fixed when settled, else the one bound by a statement, else
     *  {@code live} (the amount at the rate in force on its date; null: none). */
    public String due(String live) {
        if (settledDue != null) return settledDue;
        return stated ? statedDue : live;
    }

    /** The audit suffix: {@code " number=<n>"} for a claim that has a number. */
    @JsonIgnore
    public String getAuditNumber() {
        return number == null ? "" : " number=" + number;
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Closes a period, fixing its due-total as it is now: the due of the claims that count whose date
 *  falls in it (n/a ones skipped, and OPEN ones of people on hold), as the screen shows them.
 *  Refused when it is already closed. */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets,
            Out<Period> period) throws InvalidPeriodException, PeriodClosedException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (found.closed()) {
            throw new PeriodClosedException("The period is already closed");
        }
        String floor = settings.floor(id);
        Dues.Late late = settings.late(id, sheets.today(id));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.list(id)) {
            if (!c.isCounting() || !found.contains(c.getDate())) continue;
            Person person = people.find(id, c.getPersonId());
            if (person != null && !person.countsLive(c)) continue;
            Rate rate = person == null ? null
                    : rates.find(id, person.gradeOn(c.getDate()), LocalDate.parse(c.getDate()));
            String due = Dues.shown(c, rate == null ? null : Dues.of(c.getAmount(), rate.pct(), floor), late);
            if (due != null) total = total.add(new BigDecimal(due));
        }
        period.set(periods.close(found, total, by == null ? "" : by));
    }
}
import { getJson, postJson, putJson } from '../../api/http';
import { sheetKey } from '../sheet/api';

/** A claim's status: DRAFT, opened to OPEN, settled to SETTLED; a DRAFT or OPEN claim can be voided. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
/** A change of a claim's status. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** A claim: its amount as two-decimal text, its date (yyyy-MM-dd), its note, its status and its
 *  number on the sheet (given when opened; null while a draft or once voided), and its settled due
 *  (fixed when settled; null otherwise, or when there was no rate then — its due stays live), and who
 *  opened it (null while a draft; that user cannot settle it), and whether its person's last statement
 *  bound it, with the figure it bound (null when it had none): a bound claim shows and totals that.
 *  A correction (a negative amount) has the number of the SETTLED claim it corrects (null otherwise). */
export type Claim = {
  id: number; sheetId: string; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  number: number | null; settledDue: string | null; openedBy: string | null;
  stated: boolean; statedDue: string | null; corrects: number | null;
};
/** `corrects`: the number of the SETTLED claim of the same person a correction (a negative amount) corrects. */
export type ClaimInput = { amount: string; date: string; note: string; corrects: string };

/** Whether a claim is a correction: its amount is negative. */
export const isCorrection = (c: Pick<Claim, 'amount'>) => c.amount.trim().startsWith('-') && Number(c.amount) !== 0;

const sheetBase = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function listClaims(sheetId: string): Promise<Claim[]> {
  return getJson<Claim[]>(`${sheetBase(sheetId)}/claims`);
}

/** Add a claim to a person; refused (rejects) when the amount is missing or has more than two
 *  decimals, the date is not a date, or it is a correction (negative) that does not name by number a
 *  SETTLED claim of the person. A blank date takes the sheet's today. */
export function addClaim(sheetId: string, by: string, personId: number, input: ClaimInput): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/people/${personId}/claims?by=${encodeURIComponent(by)}`, input);
}

/** Edit a claim; refused (rejects) like an add. */
export function updateClaim(sheetId: string, by: string, id: number, input: ClaimInput): Promise<Claim> {
  return putJson<Claim>(`${sheetBase(sheetId)}/claims/${id}?by=${encodeURIComponent(by)}`, input);
}

/** Change a claim's status; refused (rejects) when its status does not allow the change, or when the
 *  user settling it is the one who opened it. */
export function moveClaim(sheetId: string, by: string, id: number, action: ClaimAction): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/${action}?by=${encodeURIComponent(by)}`, {});
}

/** Whether a claim counts toward claimed, due-total and every total: only OPEN and SETTLED do. */
export const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

/** The claims that count in live totals: all but the OPEN claims of people on hold (their SETTLED
 *  claims still count). */
export function liveClaims(claims: Claim[], people: Array<{ id: number; held: boolean }> | undefined): Claim[] {
  const held = new Set((people ?? []).filter((p) => p.held).map((p) => p.id));
  return claims.filter((c) => !(c.status === 'OPEN' && held.has(c.personId)));

